PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate ?deathDate
WHERE {
  VALUES ?person { dbr:Theodore_McMillian dbr:Hillel_Slovak }

  OPTIONAL { ?person dbp:birthDate ?birthDate . }
  OPTIONAL { ?person dbp:deathDate ?deathDate . }

  OPTIONAL {
    FILTER (!BOUND(?birthDate))
    ?person dbo:birthDate ?birthDate .
  }
  OPTIONAL {
    FILTER (!BOUND(?deathDate))
    ?person dbo:deathDate ?deathDate .
  }
}
LIMIT 100

